from pathlib import Path
import json

p = Path(__file__).resolve().parent
items = json.loads((p / 'Settings.json').read_text(encoding='utf-8'))['concepts']
page = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deadly Jenga · World Settings</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#11151b;color:#f3efe5;font:16px/1.6 system-ui,sans-serif}main{max-width:1700px;margin:auto;padding:28px 3vw}a{color:#abe4d0}h1{font-size:clamp(30px,4vw,48px);line-height:1.12;margin:12px 0}h2{font-size:30px;margin:22px 0 8px}p{max-width:1050px;color:#c6cdd5}.tag{font-size:12px;letter-spacing:.16em;color:#bce8cf;text-transform:uppercase}.nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:25px 0}button,select,textarea{font:inherit;background:#202935;color:#f3efe5;border:1px solid #465465;border-radius:7px;padding:10px 14px}button{cursor:pointer;text-align:left}button[aria-pressed=true]{border-color:#b0e7d3;background:#2d4641}button:hover{border-color:#b0e7d3}.board{display:block;width:100%;height:auto;border:1px solid #465465;border-radius:9px}.actions{display:flex;flex-wrap:wrap;gap:18px;align-items:center;margin:15px 0}.meta{color:#b9c4d0;font-size:14px}.references{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:20px 0}.references img{width:100%;height:auto}.references figure{margin:0}figcaption{font-size:13px;color:#bec8d5}details{padding:18px 0;border-top:1px solid #465465;margin-top:24px}summary{cursor:pointer;font-size:20px}textarea{display:block;width:100%;min-height:85px;margin:12px 0}.status{font-size:13px;color:#bce8cf;min-height:25px}footer{border-top:1px solid #465465;margin-top:30px;padding-top:20px;color:#b9c4d0;font-size:14px}:focus-visible{outline:3px solid #b0e7d3;outline-offset:3px}@media(max-width:700px){.nav{grid-template-columns:1fr 1fr}.references{grid-template-columns:1fr}}@media(max-width:420px){.nav{grid-template-columns:1fr}}
</style></head><body><main><div class="tag">Deadly Jenga · Requested settings · October 26, 2026</div><h1>Eight worlds around the mayhem</h1><p>Honeycomb hive · Cotton-candy carnival · Jungle lilypad · Giant jungle leaf · Playground sandbox · Old western town · Blue-sky candy glass · Tiny moon</p><p><a href="index.html">Browse the 30 abstract surface studies →</a></p><nav id="nav" class="nav" aria-label="Setting"></nav><h2 id="title"></h2><div id="map" class="meta"></div><p id="description"></p><a id="full" target="_blank" rel="noopener"><img id="image" class="board" alt=""></a><div class="actions"><a id="download" target="_blank" rel="noopener">Open full-resolution board ↗</a><span class="meta">Each board combines the setting with three material / ornament close-ups.</span></div><p class="meta">AI art concepts based on actual Unity map images. Exact geometry can drift; these are visual proposals, not Unity captures or implemented maps. Large surrounding elements are background concepts; their collision boundaries and rendering cost need a separate implementation pass.</p><label for="review">Review this setting</label><div class="actions"><select id="review"><option value="unreviewed">Unreviewed</option><option value="favorite">Favorite</option><option value="revise">Revise</option><option value="approved">Approved concept</option></select><button id="export">Export notes</button></div><label for="notes">Notes</label><textarea id="notes" placeholder="Materials, details or atmosphere to keep or change…"></textarea><div id="status" class="status" aria-live="polite"></div><details><summary>Original Unity shape references</summary><div id="references" class="references"></div><p><a id="overview" target="_blank" rel="noopener">Open original whole-map view ↗</a></p></details><details><summary>Full visual direction</summary><p id="direction"></p><p>These are visual-child ornament proposals: sparse details on external corners, undersides and post backs. Walking tops, climbing fronts, stairs and gaps stay clear. Macro material depth is illustrative, not a requirement for expensive displacement or transparency. Texture, normal and roughness treatments should carry most of the detail.</p><p><a href="SettingPrompts.json">Exact generation prompts</a> · <a href="Settings.json">Setting specifications</a></p></details><footer>No Unity scenes, geometry, materials, physics or gameplay changed.</footer></main><script>
const items=__ITEMS__;const $=id=>document.getElementById(id);let active=0,notes={};try{notes=JSON.parse(localStorage.getItem('dj-settings-review-v1')||'{}')}catch(e){}
function render(){const e=items[active];$('title').textContent=e.title;$('map').textContent='Shape reference: '+e.mapName;$('description').textContent=e.description;$('direction').textContent=e.scene;const file=e.id+'.png';$('image').src=file;$('image').alt=e.title+' — actual '+e.mapName+' shapes restyled with three material detail insets';$('full').href=file;$('download').href=file;document.querySelectorAll('#nav button').forEach((b,i)=>b.setAttribute('aria-pressed',i===active?'true':'false'));const r=notes[e.id]||{};$('review').value=r.status||'unreviewed';$('notes').value=r.notes||'';$('status').textContent='';$('references').replaceChildren();['Street layers','Landmark detail','Rooftop connections'].forEach((label,i)=>{const f=document.createElement('figure');const a=document.createElement('a');a.href='../EpicCityCinematics-20261026/'+e.mapId+'-0'+(i+1)+'.png';a.target='_blank';a.rel='noopener';const img=document.createElement('img');img.src=a.href;img.alt=e.mapName+' original '+label;img.loading='lazy';const c=document.createElement('figcaption');c.textContent=label;a.append(img);f.append(a,c);$('references').append(f)});$('overview').href='../EpicCitiesWoven-20261025/Captures/'+String(e.number).padStart(2,'0')+'-intact.png';history.replaceState(null,'','#'+e.id)}
items.forEach((e,i)=>{const b=document.createElement('button');b.textContent=e.title;b.type='button';b.onclick=()=>{active=i;render()};$('nav').append(b)});const initial=items.findIndex(e=>e.id===location.hash.slice(1));if(initial>=0)active=initial;
function save(){const e=items[active];notes[e.id]={title:e.title,mapId:e.mapId,status:$('review').value,notes:$('notes').value};try{localStorage.setItem('dj-settings-review-v1',JSON.stringify(notes));$('status').textContent='Saved in this browser.'}catch(e){$('status').textContent='Storage unavailable; export notes to keep them.'}}$('notes').oninput=save;$('review').onchange=save;$('export').onclick=()=>{const blob=new Blob([JSON.stringify({exported:new Date().toISOString(),notes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='DeadlyJenga-six-settings-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></body></html>'''
(p / 'settings.html').write_text(page.replace('__ITEMS__',json.dumps(items)),encoding='utf-8')
print('Built eight-setting review gallery')
